import { SENATE_BASELINE, SENATE_MAJORITY } from '../config';
import type { Race, Source } from '../types';

export interface Consensus {
  /** Mean of all directly published sweep probabilities. */
  mean: number;
  min: number;
  max: number;
  count: number;
}

/** Aggregates sources that publish a joint "D House AND D Senate" probability. */
export function consensus(sources: readonly Source[]): Consensus | null {
  const values = sources.filter((s) => s.status === 'ok' && s.sweep !== null).map((s) => s.sweep as number);
  if (values.length === 0) return null;
  return {
    mean: values.reduce((a, b) => a + b, 0) / values.length,
    min: Math.min(...values),
    max: Math.max(...values),
    count: values.length,
  };
}

/** Fréchet bounds: the range a joint probability must lie in, given only the two marginals. */
export function frechetBounds(house: number, senate: number): { lo: number; hi: number } {
  return { lo: Math.max(0, house + senate - 1), hi: Math.min(house, senate) };
}

/** Joint probability if House and Senate outcomes were independent. */
export function independentSweep(house: number, senate: number): number {
  return house * senate;
}

/** Ratio of the joint probability to the independence product; > 1 means positive correlation. */
export function correlationLift(sweep: number, house: number, senate: number): number {
  return sweep / independentSweep(house, senate);
}

/** Phi coefficient between "D wins House" and "D wins Senate" implied by the three probabilities. */
export function impliedPhi(sweep: number, house: number, senate: number): number {
  const denom = Math.sqrt(house * (1 - house) * senate * (1 - senate));
  return denom === 0 ? 0 : (sweep - house * senate) / denom;
}

/** Mean of the available market prices for a race, or null. */
export function raceProbability(race: Pick<Race, 'kalshi' | 'polymarket'>): number | null {
  const v = [race.kalshi, race.polymarket].filter((x): x is number => x !== null);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
}

/** Poisson-binomial distribution: result[k] = P(exactly k wins), assuming independent races. */
export function seatDistribution(probs: readonly number[]): number[] {
  let dist = [1];
  for (const p of probs) {
    const next = new Array<number>(dist.length + 1).fill(0);
    dist.forEach((d, k) => {
      next[k]! += d * (1 - p);
      next[k + 1]! += d * p;
    });
    dist = next;
  }
  return dist;
}

export type Winner = 'D' | 'R';

export interface SenateOutlook {
  /** Seats Democrats need from the tracked races to reach 51. */
  needed: number;
  /** Seats Democrats would hold if every race goes to the current favorite. */
  favoriteSeats: number;
  /** Seats locked in by baseline + user picks. */
  lockedDem: number;
  /** P(Democrats ≥ 51) under independence, conditional on picks. */
  pMajorityIndependent: number;
  expectedSeats: number;
  /** Distribution over total Democratic seats (index = seat count offset by `distOffset`). */
  dist: number[];
  distOffset: number;
  /** State whose race delivers the 51st seat when races are ranked by Democratic odds. */
  tippingPoint: string | null;
}

/** Computes Senate control math for the tracked races, optionally with user-forced winners. */
export function senateOutlook(races: readonly Race[], picks: Readonly<Record<string, Winner>> = {}): SenateOutlook {
  const scored = races
    .map((r) => ({ state: r.state, p: raceProbability(r) }))
    .filter((r): r is { state: string; p: number } => r.p !== null);

  const needed = SENATE_MAJORITY - SENATE_BASELINE.dem;
  const lockedDem = SENATE_BASELINE.dem + scored.filter((r) => picks[r.state] === 'D').length;
  const open = scored.filter((r) => !picks[r.state]);
  const dist = seatDistribution(open.map((r) => r.p));
  const seatsNeededFromOpen = SENATE_MAJORITY - lockedDem;
  const pMajorityIndependent = dist.reduce((acc, d, k) => (k >= seatsNeededFromOpen ? acc + d : acc), 0);
  const expectedSeats = lockedDem + open.reduce((a, r) => a + r.p, 0);
  const favoriteSeats =
    SENATE_BASELINE.dem +
    scored.filter((r) => (picks[r.state] ? picks[r.state] === 'D' : r.p > 0.5)).length;

  const ranked = [...scored].sort((a, b) => b.p - a.p);
  const tippingPoint = ranked[needed - 1]?.state ?? null;

  return { needed, favoriteSeats, lockedDem, pMajorityIndependent, expectedSeats, dist, distOffset: lockedDem, tippingPoint };
}

/** Whole days from `now` until the election date (local midnight-agnostic, never negative). */
export function daysUntil(isoDate: string, now: Date = new Date()): number {
  const target = Date.parse(`${isoDate}T00:00:00Z`);
  return Math.max(0, Math.ceil((target - now.getTime()) / 86_400_000));
}
